using System; using System.Drawing; using System.Drawing.Drawing2D; using System.Windows.Forms; using System.Collections.Generic; using System.IO; using System.Linq; using System.Xml.Serialization;
public class EventItem { public string Name {get;set;} public DateTime Date {get;set;} public bool RepeatYearly {get;set;} public DateTime Target(DateTime today){ if(!RepeatYearly || Date.Date>today.Date) return Date.Date; int year=today.Year; DateTime candidate=new DateTime(year,Date.Month,Math.Min(Date.Day,DateTime.DaysInMonth(year,Date.Month))); if(candidate.Date<today.Date && year<9999){year++;candidate=new DateTime(year,Date.Month,Math.Min(Date.Day,DateTime.DaysInMonth(year,Date.Month)));} return candidate; } }
public class App : Form {
 List<EventItem> items=new List<EventItem>(); FlowLayoutPanel list; Label count; TextBox search; Label searchLabel; DateTime lastDay=DateTime.Today; string path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DayCounter","events.xml");
 public App(){ Text="Day Counter"; Size=new Size(1000,720); MinimumSize=new Size(600,450); StartPosition=FormStartPosition.CenterScreen; BackColor=Color.FromArgb(244,247,252); Font=new Font("Segoe UI",10); var header=new Panel{Dock=DockStyle.Top,Height=85,BackColor=Color.FromArgb(35,83,143)}; var title=new Label{Text="days / matter",ForeColor=Color.White,Font=new Font("Segoe UI",20,FontStyle.Bold),AutoSize=true,Location=new Point(25,12)}; var subtitle=new Label{Text="A little space for the days that matter.",ForeColor=Color.White,AutoSize=true,Location=new Point(29,55)}; var add=new Button{Text="+  New event",Size=new Size(135,40),Anchor=AnchorStyles.Top|AnchorStyles.Right,Location=new Point(730,22),FlatStyle=FlatStyle.Flat,BackColor=Color.White,ForeColor=Color.FromArgb(25,120,192)}; add.Click+=(s,e)=>Edit(null); header.Controls.AddRange(new Control[]{title,subtitle,add}); header.Resize+=(s,e)=>{ add.Left=header.ClientSize.Width-add.Width-25; }; Controls.Add(header); add.Left=header.ClientSize.Width-add.Width-25; var intro=new Panel{Dock=DockStyle.Top,Height=104,Padding=new Padding(25,15,25,0)}; intro.Controls.Add(new Label{Text="Your moments",Font=new Font("Segoe UI",17,FontStyle.Bold),AutoSize=true,Location=new Point(25,15)}); count=new Label{Text="",ForeColor=Color.Gray,AutoSize=true,Location=new Point(28,53)}; intro.Controls.Add(count); search=new TextBox{Width=220,Location=new Point(720,35),Anchor=AnchorStyles.Top|AnchorStyles.Right,Font=new Font("Segoe UI",10)}; search.TextChanged+=(s,e)=>Render(); searchLabel=new Label{Text="SEARCH EVENTS",AutoSize=true,Font=new Font("Segoe UI",8,FontStyle.Bold),ForeColor=Color.FromArgb(120,140,160),Top=15}; intro.Controls.Add(search); intro.Controls.Add(searchLabel); intro.Resize+=(s,e)=>{search.Left=intro.ClientSize.Width-search.Width-30;searchLabel.Left=search.Left;}; Controls.Add(intro); search.Left=intro.ClientSize.Width-search.Width-30; searchLabel.Left=search.Left; intro.BringToFront(); list=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,Padding=new Padding(20,5,20,20),WrapContents=true}; Controls.Add(list); list.BringToFront(); LoadData(); Render(); var timer=new Timer{Interval=60000}; timer.Tick+=(s,e)=>{if(lastDay!=DateTime.Today){lastDay=DateTime.Today;Render();}}; timer.Start(); }
 void LoadData(){try{if(File.Exists(path))using(var f=File.OpenRead(path)) items=(List<EventItem>)new XmlSerializer(typeof(List<EventItem>)).Deserialize(f);}catch(Exception ex){MessageBox.Show("Could not read saved events: "+ex.Message,"Day Counter",MessageBoxButtons.OK,MessageBoxIcon.Warning);} }
 bool Save(){try{Directory.CreateDirectory(Path.GetDirectoryName(path)); var temp=path+".tmp"; using(var f=File.Create(temp))new XmlSerializer(typeof(List<EventItem>)).Serialize(f,items); if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path); return true;}catch(Exception ex){MessageBox.Show("Could not save events: "+ex.Message,"Day Counter",MessageBoxButtons.OK,MessageBoxIcon.Error);return false;}}
 void Render(){list.SuspendLayout(); foreach(Control old in list.Controls.Cast<Control>().ToArray()){list.Controls.Remove(old);old.Dispose();} count.Text=items.Count+(items.Count==1?" EVENT  ·  ":" EVENTS  ·  ")+"YOUR PERSONAL TIMELINE"; if(items.Count==0){list.Controls.Add(new Label{Text="Your next important day belongs here.\n\nSelect  + New event  to get started.",AutoSize=true,Font=new Font("Segoe UI",12),ForeColor=Color.FromArgb(111,132,155),Margin=new Padding(16,30,0,0)});} if(items.Count>0 && !items.Any(x=>x.Name.IndexOf(search.Text,StringComparison.CurrentCultureIgnoreCase)>=0))list.Controls.Add(new Label{Text="No matching events. Try another search.",AutoSize=true,ForeColor=Color.Gray,Margin=new Padding(16,30,0,0)}); foreach(var item in items.Where(x=>x.Name.IndexOf(search.Text,StringComparison.CurrentCultureIgnoreCase)>=0).OrderBy(x=>Math.Abs((x.Target(DateTime.Today)-DateTime.Today).Days)).ToArray()){var card=new EventCard(item);card.Margin=new Padding(9,12,12,12);card.EditRequested+=(s,e)=>Edit(item);card.DeleteRequested+=(s,e)=>{if(MessageBox.Show("Delete this event?","Day Counter",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes){int i=items.IndexOf(item);items.RemoveAt(i);if(!Save())items.Insert(i,item);Render();}};card.FloatRequested+=(s,e)=>new FloatingCard(item).Show();list.Controls.Add(card);}list.ResumeLayout(); }
 void Edit(EventItem item){using(var d=new Form{Text=item==null?"Add an event":"Edit event",Size=new Size(410,310),FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false,StartPosition=FormStartPosition.CenterParent,Font=Font}){var name=new TextBox{Location=new Point(25,48),Width=340,MaxLength=80,Text=item==null?"":item.Name};var date=new DateTimePicker{Location=new Point(25,115),Width=340,Format=DateTimePickerFormat.Short,Value=item==null?DateTime.Today:item.Date};var repeat=new CheckBox{Text="Repeat every year",AutoSize=true,Location=new Point(25,157),Checked=item!=null && item.RepeatYearly};var save=new Button{Text="Save event",Location=new Point(260,211),Size=new Size(105,35),BackColor=Color.FromArgb(35,83,143),ForeColor=Color.White,FlatStyle=FlatStyle.Flat};var cancel=new Button{Text="Cancel",Location=new Point(170,211),Size=new Size(80,35),DialogResult=DialogResult.Cancel}; d.Controls.AddRange(new Control[]{new Label{Text="Event name",Location=new Point(25,23),AutoSize=true},name,new Label{Text="Date",Location=new Point(25,90),AutoSize=true},date,repeat,save,cancel});d.CancelButton=cancel;save.Click+=(s,e)=>{if(String.IsNullOrWhiteSpace(name.Text)){MessageBox.Show("Enter an event name.");return;} if(item==null){var added=new EventItem{Name=name.Text.Trim(),Date=date.Value.Date,RepeatYearly=repeat.Checked};items.Add(added);if(!Save()){items.Remove(added);return;}}else{string oldName=item.Name;DateTime oldDate=item.Date;bool oldRepeat=item.RepeatYearly;item.Name=name.Text.Trim();item.Date=date.Value.Date;item.RepeatYearly=repeat.Checked;if(!Save()){item.Name=oldName;item.Date=oldDate;item.RepeatYearly=oldRepeat;return;}}d.DialogResult=DialogResult.OK;d.Close();};if(d.ShowDialog(this)==DialogResult.OK)Render();}}
 [STAThread] public static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new App());}
}


public class FloatingCard : Form {
 EventItem item; Label heading, number, detail, date; Button pin; Point origin; Timer timer;
 public FloatingCard(EventItem value){item=value; Text="Day Counter - " + item.Name; ClientSize=new Size(300,235); FormBorderStyle=FormBorderStyle.None; StartPosition=FormStartPosition.Manual; var area=Screen.PrimaryScreen.WorkingArea; Location=new Point(area.Right-320,area.Top+35); TopMost=true; ShowInTaskbar=true; BackColor=Color.White; Font=new Font("Segoe UI",10); Padding=new Padding(1); var top=new Panel{Dock=DockStyle.Top,Height=52,BackColor=Color.FromArgb(35,83,143)}; heading=new Label{Location=new Point(14,13),Size=new Size(186,29),ForeColor=Color.White,Font=new Font("Segoe UI",11,FontStyle.Bold),AutoEllipsis=true}; pin=new Button{Text="PIN",Location=new Point(202,10),Size=new Size(47,30),FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(62,130,207),ForeColor=Color.White}; pin.FlatAppearance.BorderSize=0; pin.Click+=(s,e)=>{TopMost=!TopMost;pin.Text=TopMost?"PIN":"FREE";};var close=new Button{Text="×",Location=new Point(258,10),Size=new Size(30,30),FlatStyle=FlatStyle.Flat,ForeColor=Color.White};close.FlatAppearance.BorderSize=0;close.Click+=(s,e)=>Close();top.Controls.AddRange(new Control[]{heading,pin,close});number=new Label{Location=new Point(0,60),Size=new Size(300,78),TextAlign=ContentAlignment.MiddleCenter,Font=new Font("Segoe UI",42,FontStyle.Bold),ForeColor=Color.FromArgb(36,55,77)};detail=new Label{Location=new Point(0,140),Size=new Size(300,25),TextAlign=ContentAlignment.MiddleCenter,Font=new Font("Segoe UI",9,FontStyle.Bold),ForeColor=Color.FromArgb(95,130,165)};date=new Label{Location=new Point(0,177),Size=new Size(300,23),TextAlign=ContentAlignment.MiddleCenter,ForeColor=Color.FromArgb(130,147,163)};var hint=new Label{Text="DRAG THE BLUE BAR TO MOVE",Location=new Point(0,210),Size=new Size(300,17),TextAlign=ContentAlignment.MiddleCenter,Font=new Font("Segoe UI",7),ForeColor=Color.FromArgb(170,185,198)};Controls.AddRange(new Control[]{top,number,detail,date,hint}); top.MouseDown+=DragStart;top.MouseMove+=DragMove;heading.MouseDown+=DragStart;heading.MouseMove+=DragMove;timer=new Timer{Interval=1000};timer.Tick+=(s,e)=>RefreshCard();timer.Start();FormClosed+=(s,e)=>timer.Dispose();RefreshCard(); }
 void DragStart(object s,MouseEventArgs e){if(e.Button==MouseButtons.Left)origin=Cursor.Position;}
 void DragMove(object s,MouseEventArgs e){if(e.Button==MouseButtons.Left){var p=Cursor.Position;Location=new Point(Left+p.X-origin.X,Top+p.Y-origin.Y);origin=p;}}
 void RefreshCard(){int n=(item.Target(DateTime.Today)-DateTime.Today).Days; heading.Text=item.Name; number.Text=Math.Abs(n).ToString();detail.Text=n==0?"TODAY":n>0?(n==1?"DAY TO GO":"DAYS TO GO"):(n==-1?"DAY AGO":"DAYS AGO");date.Text=item.Target(DateTime.Today).ToString("MMMM d, yyyy",System.Globalization.CultureInfo.GetCultureInfo("en-US"));}
}

public class EventCard : Panel {
 EventItem item; public event EventHandler EditRequested,DeleteRequested,FloatRequested;
 static Color ink=Color.FromArgb(27,52,83), blue=Color.FromArgb(52,110,180),muted=Color.FromArgb(125,145,165);
 public EventCard(EventItem e){item=e;Size=new Size(292,282);BackColor=Color.FromArgb(244,247,252);DoubleBuffered=true; var edit=MakeButton("Edit",new Point(20,234),Color.FromArgb(237,243,250),ink);var del=MakeButton("Delete",new Point(99,234),Color.FromArgb(250,241,242),Color.FromArgb(170,88,94));var fl=MakeButton("Float ↗",new Point(178,234),Color.FromArgb(52,110,180),Color.White);edit.Click+=(s,a)=>{if(EditRequested!=null)EditRequested(this,EventArgs.Empty);};del.Click+=(s,a)=>{if(DeleteRequested!=null)DeleteRequested(this,EventArgs.Empty);};fl.Click+=(s,a)=>{if(FloatRequested!=null)FloatRequested(this,EventArgs.Empty);};Controls.AddRange(new Control[]{edit,del,fl});}
 Button MakeButton(string text,Point at,Color bg,Color fg){var b=new Button{Text=text,Location=at,Size=new Size(68,32),FlatStyle=FlatStyle.Flat,BackColor=bg,ForeColor=fg,Font=new Font("Segoe UI",9,FontStyle.Bold),Cursor=Cursors.Hand,UseVisualStyleBackColor=false};b.FlatAppearance.BorderSize=0; b.Region=new Region(Round(new Rectangle(0,0,b.Width,b.Height),9));return b;}
 public static GraphicsPath Round(Rectangle r,int radius){var p=new GraphicsPath();int d=radius*2;p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.TextRenderingHint=System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;using(var shadow=new SolidBrush(Color.FromArgb(225,232,241)))g.FillPath(shadow,Round(new Rectangle(3,5,284,274),17));using(var white=new SolidBrush(Color.White))g.FillPath(white,Round(new Rectangle(0,0,284,274),17));using(var stripe=new SolidBrush(blue))g.FillRectangle(stripe,20,23,4,34);using(var f=new Font("Segoe UI",11,FontStyle.Bold))using(var b=new SolidBrush(ink)){var fmt=new StringFormat{Trimming=StringTrimming.EllipsisCharacter,FormatFlags=StringFormatFlags.NoWrap};g.DrawString(item.Name,f,b,new RectangleF(33,22,225,28),fmt);}using(var f=new Font("Segoe UI",8,FontStyle.Bold))using(var b=new SolidBrush(muted))g.DrawString(item.RepeatYearly?"REPEATS YEARLY":"IMPORTANT DAY",f,b,33,47); int n=(item.Target(DateTime.Today)-DateTime.Today).Days;string number=Math.Abs(n).ToString();using(var f=new Font("Segoe UI",44,FontStyle.Bold))using(var b=new SolidBrush(ink))g.DrawString(number,f,b,17,71); using(var f=new Font("Segoe UI",9,FontStyle.Bold))using(var b=new SolidBrush(blue))g.DrawString(n==0?"TODAY":n>0?"DAYS TO GO":"DAYS AGO",f,b,23,149);using(var pen=new Pen(Color.FromArgb(231,238,246)))g.DrawLine(pen,20,178,264,178);using(var f=new Font("Segoe UI",10))using(var b=new SolidBrush(muted))g.DrawString(item.Target(DateTime.Today).ToString("MMMM d, yyyy",System.Globalization.CultureInfo.GetCultureInfo("en-US")),f,b,20,190);}
}
